const redShort = red => (red && red.length ? red.map(([m, r]) => `${monthsText(m)} ${N(Math.round(r * 1000) / 10)}%`).join(', ') : '없음');
const has = c => !!(c && c.i && c.i.length);
const repOf = c => (has(c) ? ben(c.r != null ? c.r : c.i[0]) : null);

