    const d2 = row.ins.filter(x => x.drop);
    if (d2.length) return { kind: 'unknown', text: '검토 대기', why: reasonText(d2.flatMap(d => d.drop)) };
    const rel = b && b.c ? `우체국은 ${b.c[0]}인 ${txt.josa(b.c[1].map(stdN).join(', '), '이')} 관련 보장을 합니다` : '';
