const f1 = v => (+v).toFixed(1);
const dia = (x, y) => `<path class="rl-dia" d="M${f1(x)} ${f1(y - 4.5)}L${f1(x + 4.5)} ${f1(y)} ${f1(x)} ${f1(y + 4.5)} ${f1(x - 4.5)} ${f1(y)}Z"/>`;
